/**
 * Updates a Starfinder compendium artwork mapping JSON file to Foundry's native format.
 * The selected file is overwritten.
 *
 * Also replace the old module.json flag:
 *
 * "flags": {
 *   "<module-id>": {
 *     "sfrpg-art": "modules/<module-id>/your-mapping.json"
 *   }
 * }
 *
 * with:
 *
 * "flags": {
 *   "compendiumArtMappings": {
 *     "sfrpg": {
 *       "mapping": "modules/<module-id>/your-mapping.json",
 *       "credit": "<em>Optional artwork credit.</em>"
 *     }
 *   }
 * }
 *
 * Credit is optional. Restart Foundry after editing module.json.
 */

ui.notifications.info("Select the original compendium artwork mapping JSON file.");

const FilePicker = foundry.applications.apps.FilePicker.implementation;

/**
 * Convert one mapped document to Foundry's CompendiumArtInfo shape.
 * Portraits and item images become `img`. Token images become `texture.src`,
 * and a single token scale becomes `texture.scaleX` and `texture.scaleY`.
 * @param {object} entry
 * @returns {object}
 */
function convertArtEntry(entry) {
  if (!entry || typeof entry !== "object" || Array.isArray(entry)) return entry;

  const converted = { ...entry };
  delete converted.entryNum;
  delete converted.actor;
  delete converted.item;
  delete converted.img;
  delete converted.token;

  let img = entry.img;
  if (typeof img !== "string" || !img) {
    if (typeof entry.actor === "string") img = entry.actor;
    else if (typeof entry.item === "string") img = entry.item;
  }

  const result = {};
  if (typeof img === "string" && img) result.img = img;
  if (typeof converted.credit === "string") {
    result.credit = converted.credit;
    delete converted.credit;
  }
  const token = convertArtToken(entry.token);
  if (token) result.token = token;
  Object.assign(result, converted);
  return result;
}

/**
 * @param {string|object|undefined} token
 * @returns {string|object|undefined}
 */
function convertArtToken(token) {
  if (typeof token === "string") return token || undefined;
  if (!token || typeof token !== "object" || Array.isArray(token)) return undefined;

  const converted = { ...token };
  const texture = { ...converted.texture };

  if (typeof converted.img === "string" && converted.img) texture.src = converted.img;
  if (typeof converted.scale === "number") {
    texture.scaleX ??= converted.scale;
    texture.scaleY ??= converted.scale;
  }

  delete converted.img;
  delete converted.scale;

  if (Object.keys(texture).length) converted.texture = texture;
  else delete converted.texture;

  return Object.keys(converted).length ? converted : undefined;
}

new FilePicker({
  callback: async (path) => {
    try {
      const pathParts = path.split("/");
      const fileName = pathParts.pop();
      const folder = `${pathParts.join("/")}/`;
      const mapData = await foundry.utils.fetchJsonWithTimeout(path);

      if (!mapData || typeof mapData !== "object" || Array.isArray(mapData)) {
        ui.notifications.error("That file is not a compendium artwork mapping.");
        return;
      }

      const converted = {};
      for (const [packName, packData] of Object.entries(mapData)) {
        if (!packData || typeof packData !== "object" || Array.isArray(packData)) continue;
        const qualifiedName = packName.startsWith("sfrpg.") ? packName : `sfrpg.${packName}`;
        converted[qualifiedName] = Object.fromEntries(
          Object.entries(packData).map(([entryId, entryData]) => [entryId, convertArtEntry(entryData)])
        );
      }

      const newFile = new File([JSON.stringify(converted, null, 4)], fileName, { type: "application/json" });
      await FilePicker.upload("data", folder, newFile, {}, { notify: false });
      ui.notifications.info(`Updated ${path}. Update your module.json compendiumArtMappings flag, then restart Foundry.`);
    } catch (error) {
      console.error(error);
      ui.notifications.error(`Failed to update the artwork mapping: ${error.message}`);
    }
  }
}).render();
